CREATE TABLE services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  description TEXT,
  duration_minutes INTEGER NOT NULL,
  price REAL NOT NULL,
  is_active BOOLEAN DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, is_package INTEGER DEFAULT 0 NOT NULL, package_duration_weeks INTEGER DEFAULT 4, package_sessions_per_week INTEGER DEFAULT 1, tenant_id INTEGER REFERENCES tenants(id));
