CREATE TABLE pets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  breed TEXT,
  size TEXT NOT NULL, -- pequeno, medio, grande
  weight_kg REAL,
  age_years INTEGER,
  special_notes TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, photo_url TEXT, coat_condition TEXT, coat_notes TEXT, owner_name TEXT, owner_phone TEXT, owner_email TEXT, professional_id INTEGER, tenant_id INTEGER REFERENCES tenants(id));
CREATE TABLE appointments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  pet_id INTEGER NOT NULL,
  service_id INTEGER NOT NULL,
  owner_name TEXT NOT NULL,
  owner_phone TEXT NOT NULL,
  owner_email TEXT,
  appointment_date DATE NOT NULL,
  appointment_time TEXT NOT NULL,
  status TEXT DEFAULT 'agendado', -- agendado, confirmado, em_andamento, concluido, cancelado
  total_price REAL,
  notes TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, professional_id INTEGER, is_package_appointment INTEGER DEFAULT 0 NOT NULL, package_parent_id INTEGER, package_session_number INTEGER, tenant_id INTEGER REFERENCES tenants(id));
CREATE TABLE appointment_services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  appointment_id INTEGER NOT NULL,
  service_id INTEGER NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE service_pricing (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  service_id INTEGER NOT NULL,
  size TEXT NOT NULL, -- pequeno, medio, grande
  base_price REAL NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, tenant_id INTEGER REFERENCES tenants(id));
