CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE tenants (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, owner_name TEXT NOT NULL, owner_email TEXT NOT NULL, owner_phone TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'trial', trial_start TEXT, trial_end TEXT, subscription_id TEXT, subscription_status TEXT, paid_until TEXT, logo_url TEXT, phone TEXT, address TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
INSERT INTO "tenants" ("id","name","slug","owner_name","owner_email","owner_phone","plan","trial_start","trial_end","subscription_id","subscription_status","paid_until","logo_url","phone","address","created_at","updated_at") VALUES(10,'Pet Test','pet-test','Teste','admin@teste.com','11981170117','trial','2026-05-11 21:29:26','2026-05-25 21:29:26',NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-11 21:29:26','2026-05-11 21:29:26');
CREATE TABLE tenant_users (id INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id INTEGER NOT NULL REFERENCES tenants(id), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'owner', created_at TEXT DEFAULT (datetime('now')));
