CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id INTEGER NOT NULL REFERENCES tenants(id), mp_payment_id TEXT, mp_subscription_id TEXT, amount REAL NOT NULL, currency TEXT NOT NULL DEFAULT 'BRL', status TEXT NOT NULL, plan TEXT NOT NULL, period_start TEXT, period_end TEXT, raw_data TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE appointment_packages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  pet_id INTEGER NOT NULL REFERENCES pets(id),
  service_id INTEGER NOT NULL REFERENCES services(id),
  total_sessions INTEGER NOT NULL DEFAULT 4,
  completed_sessions INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT DEFAULT (datetime('now'))
);
